import{_ as s,o as t,c as a,ag as i}from"./chunks/framework.B7PviQjB.js";const k=JSON.parse('{"title":"REST API","description":"The Wafflebase REST API reads and writes the documents in a workspace over HTTP, with an API key or a signed-in session.","frontmatter":{"title":"REST API","description":"The Wafflebase REST API reads and writes the documents in a workspace over HTTP, with an API key or a signed-in session.","type":"overview"},"headers":[],"relativePath":"developers/api/index.md","filePath":"developers/api/index.md"}'),o={name:"developers/api/index.md"};function n(d,e,r,h,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h1><p>The Wafflebase REST API reads and writes the documents in a workspace over HTTP, with an API key or a signed-in session.</p><p>Use it to:</p><ul><li>Load data into a sheet from a script or a CI job, and read results back</li><li>Generate docs, notes, and decks from templates or other systems</li><li>Let an agent read a board&#39;s sticky notes and cluster them into sections</li></ul><p>The <a href="/docs/developers/cli/"><code>wafflebase</code> CLI</a> is built on these same endpoints. Reach for the CLI in a terminal and for the API when you write your own client.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li><a href="/docs/developers/api/quickstart.html#_1-create-an-api-key">Create an API key</a> in your workspace settings.</li><li><a href="/docs/developers/api/quickstart.html#_3-list-your-documents">List your documents</a> with <code>curl</code>.</li><li><a href="/docs/developers/api/quickstart.html#_4-create-a-sheet-and-write-cells">Write cells into a new sheet</a> and read them back.</li></ol><p>The <a href="/docs/developers/api/quickstart.html">Quickstart</a> walks through all three in about 10 minutes.</p><h2 id="find-an-endpoint" tabindex="-1">Find an endpoint <a class="header-anchor" href="#find-an-endpoint" aria-label="Permalink to &quot;Find an endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>See</th></tr></thead><tbody><tr><td>List, create, rename, copy, file, trash, and restore documents</td><td><a href="/docs/developers/api/documents-and-folders.html#documents">Documents and folders</a></td></tr><tr><td>Create, rename, move, and delete folders</td><td><a href="/docs/developers/api/documents-and-folders.html#folders">Documents and folders</a></td></tr><tr><td>Upload a file as a document, or upload an image to embed</td><td><a href="/docs/developers/api/documents-and-folders.html#files-and-images">Documents and folders</a></td></tr><tr><td>Manage tabs, read and write cells, insert or move rows and columns</td><td><a href="/docs/developers/api/sheets.html">Sheets</a></td></tr><tr><td>Set freeze panes, merges, styles, sizes, rules, charts, images, filters, and pivots</td><td><a href="/docs/developers/api/sheets.html#worksheet-settings">Sheets</a></td></tr><tr><td>Read or replace a doc, deck, note, or board as JSON</td><td><a href="/docs/developers/api/content.html#read-and-replace-content">Document content</a></td></tr><tr><td>Add, duplicate, move, and delete slides</td><td><a href="/docs/developers/api/content.html#slides">Document content</a></td></tr><tr><td>List, add, reply to, resolve, and delete comments</td><td><a href="/docs/developers/api/content.html#comments">Document content</a></td></tr><tr><td>Add sticky notes, sections, and text to a board, and move elements</td><td><a href="/docs/developers/api/board.html">Boards</a></td></tr></tbody></table><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><p>Every endpoint lives under <code>/api/v1/</code>. Most are scoped to one workspace:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.wafflebase.io/api/v1/workspaces/&lt;workspace&gt;</span></span></code></pre></div><p><code>https://api.wafflebase.io</code> is the hosted service. On a self-hosted server, use the origin your backend is served from; see <a href="/docs/developers/self-hosting/">Self-hosting</a>.</p><p><code>&lt;workspace&gt;</code> is the workspace ID or its slug. The slug is the part after <code>/w/</code> in the address bar when the workspace is open in your browser.</p><p>The examples on these pages use three shell variables. Set them once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WFB_API</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://api.wafflebase.io/api/v1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WFB_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wfb_your_key_here</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">acme</span></span></code></pre></div><h2 id="authenticate" tabindex="-1">Authenticate <a class="header-anchor" href="#authenticate" aria-label="Permalink to &quot;Authenticate&quot;">​</a></h2><p>Every request carries one of two credentials:</p><table tabindex="0"><thead><tr><th>Credential</th><th>How to send it</th><th>What it can do</th></tr></thead><tbody><tr><td>API key</td><td><code>Authorization: Bearer wfb_...</code></td><td>Acts as the member who created it, in the one workspace it was created for, limited by its scopes</td></tr><tr><td>Session cookie</td><td>The cookie your browser holds after you sign in</td><td>Acts as you, in every workspace you belong to</td></tr></tbody></table><p>A bearer token that starts with <code>wfb_</code> is treated as an API key. Any other request is checked for a session cookie.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/workspaces/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/documents&quot;</span></span></code></pre></div><p>This lists the documents in the workspace.</p><div class="danger custom-block"><p class="custom-block-title">Keep API keys secret</p><p>An API key can read, change, and delete everything its creator can in that workspace. Store it in a secret manager or environment variable, never in source control, and revoke it in workspace settings if it leaks.</p></div><h3 id="what-an-api-key-can-reach" tabindex="-1">What an API key can reach <a class="header-anchor" href="#what-an-api-key-can-reach" aria-label="Permalink to &quot;What an API key can reach&quot;">​</a></h3><ul><li><strong>One workspace.</strong> A key used against another workspace gets <code>403 API key is not scoped to this workspace</code>.</li><li><strong>Its creator&#39;s role, checked on every request.</strong> A plain member&#39;s key can trash only the documents that member created; an owner&#39;s key can trash any. If the creator leaves the workspace, the key stops working.</li><li><strong>Its scopes.</strong> A key has the <code>read</code> and <code>write</code> scopes by default. Every <code>POST</code>, <code>PUT</code>, <code>PATCH</code>, and <code>DELETE</code> needs <code>write</code>; without it the request gets <code>403 This API key does not have write access</code>. <code>GET</code> requests never need <code>write</code>.</li></ul><p>To manage keys, open the workspace and click <strong>Settings</strong> in the sidebar. The <strong>API keys</strong> section lists your keys. A workspace owner sees and can revoke every member&#39;s keys.</p><h3 id="create-a-read-only-key" tabindex="-1">Create a read-only key <a class="header-anchor" href="#create-a-read-only-key" aria-label="Permalink to &quot;Create a read-only key&quot;">​</a></h3><p>The <strong>Create API key</strong> dialog and <code>wafflebase api-keys create</code> always create a key with both scopes. A key with only <code>read</code> suits a script that only reads, such as a nightly report, because it cannot change or replace content. To create one, call the key endpoint with your signed-in session instead of an API key.</p><ol><li><p>Sign in to Wafflebase in your browser and open any page of the app.</p></li><li><p>Open the browser&#39;s developer console.</p></li><li><p>Run this, with your API origin and workspace slug:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.wafflebase.io/workspaces/acme/api-keys&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  method: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;POST&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  credentials: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;include&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  headers: { </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Content-Type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;application/json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  body: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Nightly report&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, scopes: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> r.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div></li><li><p>Copy the <code>key</code> field from the result. It is shown only once.</p></li></ol><p>This endpoint is outside <code>/api/v1/</code> and accepts only a session. It also takes an optional <code>expiresAt</code> (an ISO 8601 date) after which the key stops working.</p><h2 id="requests-and-responses" tabindex="-1">Requests and responses <a class="header-anchor" href="#requests-and-responses" aria-label="Permalink to &quot;Requests and responses&quot;">​</a></h2><ul><li>Send bodies as JSON with <code>Content-Type: application/json</code>, except uploads, which are <code>multipart/form-data</code>.</li><li>Responses are JSON unless an endpoint returns file bytes.</li><li>Row and column indices in the sheet endpoints are 1-based, and so are tab and slide positions. Board endpoints use canvas coordinates instead.</li><li>A document in another workspace, or one in the trash, answers <code>404 Document not found</code>, the same as one that does not exist.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>Errors use HTTP status codes with a JSON body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;statusCode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">404</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Document not found&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Not Found&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>message</code> is a string, or an array of strings when several body fields fail validation at once.</p><table tabindex="0"><thead><tr><th>Status</th><th>Usually means</th></tr></thead><tbody><tr><td><code>400</code></td><td>The body or a parameter is invalid; <code>message</code> names the field. Also returned when an endpoint is called on the wrong document type, for example <code>Tabs are only available on sheet documents; &quot;&lt;id&gt;&quot; is a &quot;doc&quot; document.</code></td></tr><tr><td><code>401</code></td><td>The credential is missing, unknown, revoked (<code>API key has been revoked</code>), or expired (<code>API key has expired</code>)</td></tr><tr><td><code>403</code></td><td>The key is for another workspace, lacks <code>write</code>, or the caller is not allowed to do this (for example, trashing someone else&#39;s document as a plain member)</td></tr><tr><td><code>404</code></td><td>The document, tab, folder, slide, comment, or element does not exist in this workspace, or the document is in the trash</td></tr><tr><td><code>409</code></td><td>The request conflicts with the document&#39;s state, such as deleting a sheet&#39;s last tab or a duplicate tab name</td></tr><tr><td><code>410</code></td><td>A share link used to read an image has expired</td></tr><tr><td><code>413</code></td><td>An uploaded file is over the size limit</td></tr><tr><td><code>429</code></td><td>You hit the rate limit; wait and retry</td></tr></tbody></table><p>The <code>/content</code> endpoints answer a sheet, PDF, image, or file document with a structured <code>409</code> instead:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TYPE_MISMATCH&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Use &#39;sheets cells get&#39; for spreadsheet documents&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><h2 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate limits&quot;">​</a></h2><p>Limits are counted per client IP address per minute:</p><table tabindex="0"><thead><tr><th>Routes</th><th>Requests per minute</th></tr></thead><tbody><tr><td>Most routes</td><td>120</td></tr><tr><td><code>POST /workspaces/&lt;workspace&gt;/files</code>, <code>GET /workspaces/&lt;workspace&gt;/files/&lt;id&gt;</code></td><td>600</td></tr><tr><td><code>POST /workspaces/&lt;workspace&gt;/images</code>, <code>GET</code> and <code>DELETE /workspaces/&lt;workspace&gt;/images/&lt;id&gt;</code></td><td>600</td></tr><tr><td><code>POST /shared/images</code></td><td>30</td></tr></tbody></table><p>A request over the limit gets <code>429</code>.</p><h2 id="routes-outside-workspace-authentication" tabindex="-1">Routes outside workspace authentication <a class="header-anchor" href="#routes-outside-workspace-authentication" aria-label="Permalink to &quot;Routes outside workspace authentication&quot;">​</a></h2><p>Two routes accept a share-link token in place of an API key or session:</p><ul><li><code>GET /workspaces/&lt;workspace&gt;/images/&lt;imageId&gt;?token=&lt;shareToken&gt;</code> reads an embedded image.</li><li><code>POST /shared/images?token=&lt;shareToken&gt;</code> uploads an image with an editor share link.</li></ul><p>Both are described in <a href="/docs/developers/api/documents-and-folders.html#files-and-images">Upload files and images</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/developers/api/quickstart.html">Make your first API call</a> with a new key.</li><li><a href="/docs/developers/api/documents-and-folders.html">Documents and folders</a> to organize a workspace from a script.</li><li><a href="/docs/developers/cli/">Use the CLI</a> when you would rather not write HTTP calls.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to understand share-link tokens.</li></ul>`,50)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
